import os
root='../../src'
total=0; per={}
for dirp,_,files in os.walk(root):
    for f in files:
        if not f.endswith('.rs'): continue
        p=os.path.join(dirp,f); cut=None
        for i,l in enumerate(open(p),1):
            if '#[cfg(test)]' in l: cut=i; break
        n=0
        for i,l in enumerate(open(p),1):
            if cut and i>=cut: break
            s=l.strip()
            if '.unwrap()' in l and not s.startswith('//') and 'description = ' not in l:
                n+=l.count('.unwrap()')
        if n: per[os.path.relpath(p,root)]=n; total+=n
print('non-test .unwrap() calls in src/:', total)
print(per)
